@ModuleInfo(name = "Debugger", description = "Debugs packets", category = Category.OTHER)
public final class Debugger extends Module {

    @Override
    public void onPacketReceive(final PacketReceiveEvent event) {
        final Packet<?> packet = event.getPacket();

        if (packet instanceof S32PacketConfirmTransaction) {
            final S32PacketConfirmTransaction wrapper = ((S32PacketConfirmTransaction) packet);

            Rise.addChatMessage("Transaction | id: " + wrapper.getActionNumber());
        }

        if (packet instanceof S00PacketKeepAlive) {
            final S00PacketKeepAlive wrapper = ((S00PacketKeepAlive) packet);

            Rise.addChatMessage("KeepAlive | id: " + wrapper.func_149134_c());
        }
    }
}


// NOTE (AI): Debugger never mutates the packet, so the vanilla echo in NetHandlerPlayClient.handleKeepAlive still fires and the ping EMA updates normally. It exists to expose keepalive cadence and ids in chat, which is exactly the information the authors needed when tuning the ping-spoof and disabler timings elsewhere in the client. The paired S32 logging shows keepalive and transaction were inspected together, matching the Verus-style correlation anti-cheats use.

